import assert from'node:assert/strict';import path from'node:path';import{writeFile}from'node:fs/promises';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';
const artifact=path.resolve('artifacts/platform/events-heldout'),cases=[];let browser,server;
try{server=await serveStatic(path.join(artifact,'project/output'));browser=await chromium.launch({channel:'chrome'});for(const width of [1440,390])for(const [view,date,sourceRoute,exportRoute]of [['day','2028-06-17','/events/2028-06-17/','/events/2028-03-11/'],['month','2028-04-01','/events/month/2028-04/','/events/month/2028-03/'],['list','2028-07-01','/events/?tribe-bar-date=2028-07-01','/events/']]){const pair=[];for(const [kind,url]of [['source','http://127.0.0.1:9440'+sourceRoute],['export',server.url+exportRoute+'?calendar-date='+date]]){const page=await browser.newPage({viewport:{width,height:900}});assert.equal((await page.goto(url,{waitUntil:'networkidle'})).status(),200);if(kind==='export')await page.waitForFunction(date=>document.querySelector('.tribe-events-c-top-bar__datepicker-time')?.getAttribute('datetime')===date,date);const labels=await page.locator('.tribe-events-c-top-bar__datepicker-time span').allTextContents();pair.push({kind,labels:labels.map(x=>x.replace(/\s+/g,' ').trim())});await page.locator('.tribe-events-c-top-bar__datepicker-button').screenshot({path:path.join(artifact,`date-label-${kind}-${view}-${width}.png`)});await page.close();}assert.deepEqual(pair[0].labels,pair[1].labels);cases.push({width,view,date,pair});}await writeFile(path.join(artifact,'date-label-generated-check.json'),JSON.stringify({scope:'Source/emitted date labels after local date navigation at two widths; paginated list ranges/custom formats remain pending',cases},null,2));console.log(JSON.stringify({cases}));}finally{await browser?.close();await server?.close();}
